"reason": null, "identity_status": "resolved", "machine": "perlmutter", "hpc_username": "mahf708", "case_name": "R2.dp-equilibrium", "execution_id": "59694792.261011-214404", "identity_matches_path": true, "simulation_start_date": "2000-01-01", "simulation_end_date": "2000-01-21", "run_start_date": "2026-10-11 21:44:04", "run_end_date": "2026-10-11 22:04:24"}, {"original_http_statuses": "409", "original_final_outcome": "failed", "archive_case_path": "/OLD_PERF/2026-10/performance_archive_2026_10_16_10_03_35/COMPLETED/tang30/WCYCL20TR_ne30pg2_r05_IcoswISC30E3r5_4DEnVarOcn_1982050100.EN06", "local_case_path": "/global/cfs/cdirs/e3sm/OLD_PERF/2026-10/performance_archive_2026_10_16_10_03_35/COMPLETED/tang30/WCYCL20TR_ne30pg2_r05_IcoswISC30E3r5_4DEnVarOcn_1982050100.EN06", "directory_execution_id": "59789650.261014-211155", "execution_path": "/global/cfs/cdirs/e3sm/OLD_PERF/2026-10/performance_archive_2026_10_16_10_03_35/COMPLETED/tang30/WCYCL20TR_ne30pg2_r05_IcoswISC30E3r5_4DEnVarOcn_1982050100.EN06/59789650.261014-211155", "source_execution_path": "/global/cfs/cdirs/e3sm/OLD_PERF/2026-10/performance_archive_2026_10_16_10_03_35/COMPLETED/tang30/WCYCL20TR_ne30pg2_r05_IcoswISC30E3r5_4DEnVarOcn_1982050100.EN06/59789650.261014-211155", "fresh_discovery_qualified": true, "inventory_status": "qualified", "reason": null, "identity_status": "resolved", "machine": "perlmutter", "hpc_username": "tang30", "case_name": "WCYCL20TR_ne30pg2_r05_IcoswISC30E3r5_4DEnVarOcn_1982050100.EN06", "execution_id": "59789650.261014-211155", "identity_matches_path": true, "simulation_start_date": "1982-05-01", "simulation_end_date": "1984-05-01", "run_start_date": "2026-10-14 21:11:56", "run_end_date": "2026-10-15 09:12:33"}]$inventory_8291bb8c693745e7b16870e29bb54c32$::jsonb) AS i(
        original_http_statuses text, original_final_outcome text,
        archive_case_path text, local_case_path text, directory_execution_id text,
        execution_path text, source_execution_path text,
        fresh_discovery_qualified boolean, inventory_status text, reason text,
        identity_status text, machine text, hpc_username text, case_name text,
        execution_id text, identity_matches_path boolean,
        simulation_start_date text, simulation_end_date text, run_start_date text, run_end_date text
    )
), checked AS (
    SELECT i.*, c.id AS case_id, e.id AS execution_record_id,
        CASE
            WHEN i.fresh_discovery_qualified IS DISTINCT FROM true THEN i.inventory_status
            WHEN i.identity_status <> 'resolved' THEN 'identity_unresolved'
            WHEN m.id IS NULL THEN 'missing_machine'
            WHEN c.id IS NULL THEN 'missing_case'
            WHEN e.id IS NULL THEN 'missing_execution'
            ELSE 'execution_exists'
        END AS database_status,
        CASE WHEN e.id IS NULL THEN NULL ELSE EXISTS (
            SELECT 1 FROM source_directories sd
            WHERE sd.execution_id = e.id AND sd.kind = 'archive'
        ) END AS has_any_archive_mapping,
        CASE WHEN e.id IS NULL THEN NULL ELSE EXISTS (
            SELECT 1 FROM source_directories sd
            WHERE sd.execution_id = e.id AND sd.kind = 'archive'
              AND sd.path = i.source_execution_path
        ) END AS has_exact_archive_mapping
    FROM inventory i
    LEFT JOIN machines m ON m.name = i.machine
    LEFT JOIN cases c ON c.machine_id = m.id
        AND c.hpc_username = i.hpc_username AND c.name = i.case_name
    LEFT JOIN executions e ON e.case_id = c.id AND e.execution_id = i.execution_id
)
SELECT database_status, COUNT(*) AS observations,
    COUNT(DISTINCT archive_case_path) AS affected_case_paths,
    COUNT(*) FILTER (WHERE fresh_discovery_qualified) AS fresh_discovery_qualified,
    COUNT(*) FILTER (WHERE identity_status = 'resolved') AS resolved_identities,
    COUNT(*) FILTER (WHERE execution_record_id IS NOT NULL AND NOT has_exact_archive_mapping)
        AS existing_observations_without_exact_mapping
FROM checked GROUP BY database_status ORDER BY database_status;

